package io.knowledgebrain.integration;
import java.util.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;import jakarta.servlet.http.HttpServletRequest;
import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
/** Narrow canonical event recovery. Integration owns and reads only its own Outbox. */
@RestController @ConditionalOnProperty(name="brain.integration.activity-export.enabled",havingValue="true")
final class ActivityExportController {
 record Item(UUID eventId,String topic,String payload){}record Page(UUID through,UUID nextAfter,List<Item> items){}
 private final JdbcTemplate jdbc;private final byte[] key;private final MeterRegistry metrics;
 ActivityExportController(DataSource ds,@Value("${brain.integration.activity-export.key}")String key,MeterRegistry metrics){if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Scoped export key required");jdbc=new JdbcTemplate(ds);this.key=("Bearer "+key).getBytes(StandardCharsets.US_ASCII);this.metrics=metrics;}
 @GetMapping("/internal/integration/activity-events") ResponseEntity<Page> page(@RequestParam(required=false)UUID after,@RequestParam(required=false)UUID through,HttpServletRequest r){var auth=Collections.list(r.getHeaders("Authorization"));if(!r.isSecure()||auth.size()!=1||!MessageDigest.isEqual(key,auth.getFirst().getBytes(StandardCharsets.UTF_8))||r.getHeader("Cookie")!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Scoped service authority required");GitHubController.query(r,Set.of("after","through"));if(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw GitHubRules.bad();if(after!=null)GitHubRules.id(after.toString());if(through!=null)GitHubRules.id(through.toString());if(through==null){var max=jdbc.queryForList("SELECT id FROM outbox_event WHERE schema_group='integration' AND schema_version='1' AND aggregatetype IN ('github-commit','github-issue','github-pull-request') ORDER BY id DESC LIMIT 1",UUID.class);through=max.isEmpty()?null:max.getFirst();}if(after!=null&&(through==null||after.toString().compareTo(through.toString())>0))throw GitHubRules.bad();List<Item> rows=through==null?List.of():jdbc.query("SELECT id,aggregatetype,payload FROM outbox_event WHERE schema_group='integration' AND schema_version='1' AND aggregatetype IN ('github-commit','github-issue','github-pull-request') AND id<=?"+(after==null?"":" AND id>?")+" ORDER BY id LIMIT 6",(rs,n)->new Item(rs.getObject(1,UUID.class),"integration."+rs.getString(2)+".v1",Base64.getEncoder().encodeToString(rs.getBytes(3))),after==null?new Object[]{through}:new Object[]{through,after});var items=List.copyOf(rows.subList(0,Math.min(rows.size(),5)));metrics.counter("brain.integration.activity.exports").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new Page(through,rows.size()>5?items.getLast().eventId():null,items));}
}
